[CmdletBinding()]
param([Parameter(Mandatory)][string]$RunId,[Parameter(Mandatory)][string]$RootRunId,[Parameter(Mandatory)][string]$PABuildRunPath,[Parameter(Mandatory)][string]$RuntimeControllerPath,[Parameter(Mandatory)][string]$CampaignPath,[Parameter(Mandatory)][string]$ReleaseSpecPath,[Parameter(Mandatory)][string]$InitialAnalysisPath,[Parameter(Mandatory)][string]$WorkspaceRoot,[Parameter(Mandatory)][string]$ArtifactRoot,[string]$PythonExe='',[string]$SimionExe='')
Set-StrictMode -Version Latest;$ErrorActionPreference='Stop'
$workspaceRoot=(Resolve-Path -LiteralPath $WorkspaceRoot).Path;$artifactRoot=$ExecutionContext.SessionState.Path.GetUnresolvedProviderPathFromPSPath($ArtifactRoot);$repoRoot=$workspaceRoot
$python=if($PythonExe){[IO.Path]::GetFullPath($PythonExe)}elseif($env:SIMULATION_PYTHON_EXE){[IO.Path]::GetFullPath($env:SIMULATION_PYTHON_EXE)}else{throw 'Explicit PythonExe or SIMULATION_PYTHON_EXE is required'}
$packageRootText=& $python -I -B -c 'from pathlib import Path;import msplatform;print(Path(msplatform.__file__).resolve().parent)'
if($LASTEXITCODE-ne0){throw 'Installed msplatform package is unavailable.'};$packageRoot=(Resolve-Path -LiteralPath $packageRootText).Path
$executionResources=Join-Path $packageRoot 'execution/resources';$simionResources=Join-Path $packageRoot 'backends/simion/resources'
. (Join-Path $executionResources 'workspace_paths.ps1');$componentArtifactRoot=Resolve-RunArtifactRoot -ArtifactRoot $artifactRoot -OwnerKind component -OwnerId orthogonal_accelerator -Python $python
. (Join-Path $executionResources 'require_powershell7.ps1');. (Join-Path $executionResources 'run_artifact_support.ps1')
$runner=Join-Path $simionResources 'run_component_focus_flight.ps1';$package=New-RunPackage -Python $python -RepoRoot $repoRoot -ArtifactRoot ($componentArtifactRoot) -RunId $RunId -Project orthogonal_accelerator -Mode component_focus_field_contrast -Software @('SIMION 2020','Python 3.11') -RetentionContractEnabled -RetentionClass solver_review -RetentionReason 'Runtime two-zone ideal-field attribution on one published native Fast-Adjust PA.' -CapacityLedgerLifecycleEnabled
$done=$false;$stage='freeze_inputs';try {
 $campaign=Copy-VerifiedRunInput (Resolve-Path $CampaignPath).Path (Join-Path $package.input_dir 'campaign.json');$release=Copy-VerifiedRunInput (Resolve-Path $ReleaseSpecPath).Path (Join-Path $package.input_dir 'release_spec.json');$native=Copy-VerifiedRunInput (Resolve-Path $InitialAnalysisPath).Path (Join-Path $package.input_dir 'native_focus_analysis.json')
 $analyses=@{native=$native};$manifests=@{}
 $rootStamp=($RootRunId -split '__',2)[0]
 if($rootStamp -notmatch '^\d{8}_\d{6}$'){throw 'RootRunId does not begin with a valid artifact timestamp.'}
 $hash=[Security.Cryptography.SHA256]::Create();try{$rootToken=([BitConverter]::ToString($hash.ComputeHash([Text.Encoding]::UTF8.GetBytes($RootRunId))).Replace('-','').Substring(0,8)).ToLowerInvariant()}finally{$hash.Dispose()}
 foreach($mode in @('zone1_ideal','zone2_ideal','full_ideal')){
  $stage=$mode;$safeMode=$mode.Replace('_','-');$childRunId="$rootStamp`__sim__simion__oa-field-$safeMode-$rootToken`__r01";&$runner -RunId $childRunId -PABuildRunPath $PABuildRunPath -RuntimeControllerPath $RuntimeControllerPath -CampaignPath $campaign -ReleaseSpecPath $release -FieldMode $mode -WorkspaceRoot $workspaceRoot -ArtifactRoot $artifactRoot -PythonExe $python -SimionExe $SimionExe;if($LASTEXITCODE-ne0){throw "Ideal-field child failed: $mode"}
  $child=Join-Path $componentArtifactRoot (Join-Path 'runs' $childRunId);$analyses[$mode]=Join-Path $child 'results\focus_analysis.json';$manifests[$mode]=(Get-FileHash (Join-Path $child 'run_manifest.json') -Algorithm SHA256).Hash
 }
 $out=Join-Path $package.result_dir 'two_zone_ideal_field_contrast.json';&$python -I -B -m msplatform.workflows.oa_focus_field_contrast --native $analyses.native --zone1-ideal $analyses.zone1_ideal --zone2-ideal $analyses.zone2_ideal --full-ideal $analyses.full_ideal --output $out;if($LASTEXITCODE-ne0){throw 'Ideal field contrast analysis failed'}
 $summary=[ordered]@{schema_version=1;role='orthogonal_accelerator_component_focus_field_contrast';status='diagnostic';native_analysis_sha256=(Get-FileHash $native -Algorithm SHA256).Hash;child_manifest_sha256=$manifests;contrast_sha256=(Get-FileHash $out -Algorithm SHA256).Hash};Write-RunJson -Path $package.summary -Depth 16 -Value $summary;$retention=Apply-RunArtifactRetention -Python $python -RepoRoot $repoRoot -RunConfig $package.run_config;Write-VerifiedRunManifest -Python $python -RepoRoot $repoRoot -RunConfig $package.run_config -Status success -Software @('SIMION 2020','Python 3.11') -Outputs @($package.summary,$retention,$out);$done=$true
}catch{throw
}finally{if(-not$done){Complete-FailedRun -Python $python -RepoRoot $repoRoot -RunConfig $package.run_config -Summary $package.summary -SummaryRole orthogonal_accelerator_component_focus_field_contrast -Reason "Ideal-field contrast failed at $stage." -Software @('SIMION 2020','Python 3.11') -Status failed};Remove-RunPackageExecutionAlias -Package $package}
